{
  "name": "ChowkDirect - Local Worker App",
  "description": "A hyperlocal platform connecting daily-wage workers (electricians, plumbers, laborers) directly with customers in their vicinity. Simple, fast, and middleman-free.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export type UserRole = 'worker' | 'customer';

export type SkillCategory = 
  | 'Electrician' 
  | 'Plumber' 
  | 'Painter' 
  | 'Helper' 
  | 'Cleaner' 
  | 'Carpenter' 
  | 'Laborer' 
  | 'Gardener';

export interface Location {
  lat: number;
  lng: number;
  address?: string;
}

export interface WorkerProfile {
  id: string;
  name: string;
  phone: string;
  photo: string;
  skill: SkillCategory;
  experience: number;
  rating: number;
  isAvailable: boolean;
  location: Location;
  distance?: number; // In km, calculated at runtime
}

export interface AppState {
  role: UserRole | null;
  userProfile: any | null;
  isLoggedIn: boolean;
}

import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import { WorkerProfile, Location } from '../types';

interface MapViewProps {
  center: Location;
  workers: WorkerProfile[];
  onWorkerClick: (worker: WorkerProfile) => void;
}

const MapView: React.FC<MapViewProps> = ({ center, workers, onWorkerClick }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<L.Map | null>(null);
  const markersGroup = useRef<L.LayerGroup | null>(null);

  useEffect(() => {
    if (mapRef.current && !leafletMap.current) {
      leafletMap.current = L.map(mapRef.current).setView([center.lat, center.lng], 14);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors'
      }).addTo(leafletMap.current);

      markersGroup.current = L.layerGroup().addTo(leafletMap.current);
    }

    return () => {
      if (leafletMap.current) {
        leafletMap.current.remove();
        leafletMap.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (leafletMap.current && markersGroup.current) {
      markersGroup.current.clearLayers();

      // Add User location marker
      L.marker([center.lat, center.lng], {
        icon: L.divIcon({
          className: 'bg-blue-500 w-4 h-4 rounded-full border-2 border-white shadow-lg',
          html: '',
          iconSize: [16, 16]
        })
      }).addTo(markersGroup.current);

      // Add Worker markers
      workers.forEach(worker => {
        if (worker.isAvailable) {
          const marker = L.marker([worker.location.lat, worker.location.lng], {
            icon: L.divIcon({
              className: 'relative',
              html: `
                <div class="bg-orange-600 p-2 rounded-full border-2 border-white shadow-xl cursor-pointer">
                   <div class="text-white text-[10px] font-bold">${worker.skill[0]}</div>
                </div>
              `,
              iconSize: [32, 32]
            })
          });

          marker.on('click', () => onWorkerClick(worker));
          marker.addTo(markersGroup.current!);
        }
      });

      leafletMap.current.setView([center.lat, center.lng]);
    }
  }, [center, workers, onWorkerClick]);

  return <div ref={mapRef} className="w-full h-full rounded-xl shadow-inner overflow-hidden" />;
};

export default MapView;

import React from 'react';
import { Phone, Star, MapPin } from 'lucide-react';
import { WorkerProfile } from '../types';

interface WorkerCardProps {
  worker: WorkerProfile;
}

const WorkerCard: React.FC<WorkerCardProps> = ({ worker }) => {
  const handleCall = () => {
    window.location.href = `tel:${worker.phone}`;
  };

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex items-center gap-4 transition-transform active:scale-[0.98]">
      <img 
        src={worker.photo} 
        alt={worker.name} 
        className="w-16 h-16 rounded-full object-cover border-2 border-gray-100" 
      />
      <div className="flex-1 min-w-0">
        <h3 className="font-bold text-gray-900 truncate">{worker.name}</h3>
        <p className="text-sm text-gray-500 font-medium">{worker.skill} • {worker.experience} yrs exp</p>
        <div className="flex items-center gap-3 mt-1">
          <div className="flex items-center text-orange-500 text-sm font-bold">
            <Star size={14} className="fill-current mr-1" />
            {worker.rating}
          </div>
          <div className="flex items-center text-gray-400 text-xs">
            <MapPin size={12} className="mr-1" />
            {worker.distance ? `${worker.distance.toFixed(1)} km` : 'Near you'}
          </div>
        </div>
      </div>
      <button 
        onClick={handleCall}
        className="bg-green-600 hover:bg-green-700 text-white p-3 rounded-full shadow-lg transition-colors flex items-center justify-center"
      >
        <Phone size={20} />
      </button>
    </div>
  );
};

export default WorkerCard;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  UserRole, 
  SkillCategory, 
  WorkerProfile, 
  Location 
} from './types';
import { SKILL_CATEGORIES, MOCK_WORKERS } from './constants';
import MapView from './components/MapView';
import WorkerCard from './components/WorkerCard';
import { 
  ChevronLeft, 
  UserCircle, 
  Phone, 
  Map as MapIcon, 
  List as ListIcon, 
  CheckCircle,
  Power,
  Settings,
  Star
} from 'lucide-react';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [step, setStep] = useState<'landing' | 'onboarding' | 'home' | 'search'>('landing');
  const [selectedSkill, setSelectedSkill] = useState<SkillCategory | null>(null);
  const [viewType, setViewType] = useState<'map' | 'list'>('list');
  const [userLocation, setUserLocation] = useState<Location>({ lat: 28.6139, lng: 77.2090 }); // Default Delhi
  const [isWorkerOnline, setIsWorkerOnline] = useState(false);
  const [workerProfile, setWorkerProfile] = useState<Partial<WorkerProfile>>({
    name: '',
    phone: '',
    skill: 'Laborer',
    experience: 0,
    photo: 'https://picsum.photos/seed/worker/200'
  });

  // Get user location on mount
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      });
    }
  }, []);

  const calculateDistance = (l1: Location, l2: Location) => {
    const R = 6371; // km
    const dLat = (l2.lat - l1.lat) * Math.PI / 180;
    const dLon = (l2.lng - l1.lng) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(l1.lat * Math.PI / 180) * Math.cos(l2.lat * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  };

  const filteredWorkers = MOCK_WORKERS
    .filter(w => !selectedSkill || w.skill === selectedSkill)
    .map(w => ({
      ...w,
      distance: calculateDistance(userLocation, w.location)
    }))
    .sort((a, b) => (a.distance || 0) - (b.distance || 0));

  const handleRoleSelection = (r: UserRole) => {
    setRole(r);
    setStep('onboarding');
  };

  const handleOnboardingSubmit = () => {
    setStep('home');
  };

  const handleSkillSelect = (skill: SkillCategory) => {
    setSelectedSkill(skill);
    setStep('search');
  };

  // Render Screens
  if (step === 'landing') {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6 text-center">
        <div className="bg-orange-600 p-6 rounded-3xl shadow-xl mb-8">
           <MapIcon size={48} className="text-white" />
        </div>
        <h1 className="text-4xl font-black text-gray-900 mb-2">ChowkDirect</h1>
        <p className="text-gray-500 mb-12 max-w-xs">Directly call local workers near you. No middleman. No fees.</p>

        <div className="w-full space-y-4 max-w-sm">
          <button 
            onClick={() => handleRoleSelection('customer')}
            className="w-full bg-orange-600 hover:bg-orange-700 text-white font-bold py-4 rounded-2xl shadow-lg transition-transform active:scale-95"
          >
            I need a Worker
          </button>
          <button 
            onClick={() => handleRoleSelection('worker')}
            className="w-full bg-white border-2 border-orange-600 text-orange-600 font-bold py-4 rounded-2xl transition-transform active:scale-95"
          >
            I am a Worker
          </button>
        </div>
      </div>
    );
  }

  if (step === 'onboarding') {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col">
        <header className="p-4 bg-white shadow-sm flex items-center">
          <button onClick={() => setStep('landing')} className="p-2"><ChevronLeft /></button>
          <h2 className="text-lg font-bold ml-2">Simple Profile</h2>
        </header>
        <div className="flex-1 p-6 space-y-6">
          <div className="space-y-4">
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Full Name</label>
              <input 
                type="text" 
                placeholder="Enter your name" 
                className="w-full p-4 mt-1 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                value={workerProfile.name}
                onChange={(e) => setWorkerProfile({...workerProfile, name: e.target.value})}
              />
            </div>
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Mobile Number</label>
              <div className="flex gap-2">
                <span className="p-4 bg-gray-200 rounded-xl font-bold">+91</span>
                <input 
                  type="tel" 
                  placeholder="98xxxxxx" 
                  className="flex-1 p-4 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                  value={workerProfile.phone}
                  onChange={(e) => setWorkerProfile({...workerProfile, phone: e.target.value})}
                />
              </div>
            </div>
            {role === 'worker' && (
              <>
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Work Category</label>
                  <select 
                    className="w-full p-4 mt-1 bg-white border border-gray-200 rounded-xl outline-none"
                    value={workerProfile.skill}
                    onChange={(e) => setWorkerProfile({...workerProfile, skill: e.target.value as SkillCategory})}
                  >
                    {SKILL_CATEGORIES.map(s => <option key={s.name} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Years of Experience</label>
                  <input 
                    type="number" 
                    placeholder="E.g. 5" 
                    className="w-full p-4 mt-1 bg-white border border-gray-200 rounded-xl outline-none"
                    value={workerProfile.experience}
                    onChange={(e) => setWorkerProfile({...workerProfile, experience: Number(e.target.value)})}
                  />
