            className="w-full bg-orange-600 disabled:bg-gray-300 text-white font-bold py-4 rounded-2xl shadow-lg mt-8 transition-transform active:scale-95"
          >
            Start Using App
          </button>
        </div>
      </div>
    );
  }

  // WORKER HOME
  if (role === 'worker' && step === 'home') {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col pb-24">
        <header className="bg-white p-6 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-black text-gray-900">Worker Dashboard</h1>
            <Settings size={24} className="text-gray-400" />
          </div>
          <div className="bg-white border-2 border-gray-100 rounded-2xl p-4 flex items-center gap-4">
             <img src={workerProfile.photo} className="w-16 h-16 rounded-full border-2 border-orange-600" />
             <div>
                <h2 className="font-bold text-lg">{workerProfile.name}</h2>
                <div className="flex items-center text-sm text-gray-500 gap-2">
                   <span className="bg-orange-100 text-orange-700 px-2 py-0.5 rounded-md font-bold text-[10px] uppercase">
                     {workerProfile.skill}
                   </span>
                   <div className="flex items-center text-orange-500 font-bold">
                      <Star size={14} className="fill-current mr-1" />
                      4.9
                   </div>
                </div>
             </div>
          </div>
        </header>

        <main className="p-6 flex-1 flex flex-col items-center justify-center space-y-8">
          <div className="text-center space-y-2">
            <h3 className={`text-2xl font-bold ${isWorkerOnline ? 'text-green-600' : 'text-red-500'}`}>
              {isWorkerOnline ? "You're Online!" : "You're Offline"}
            </h3>
            <p className="text-gray-500 max-w-[200px]">
              {isWorkerOnline 
                ? "Customers can see you on the map and call you." 
                : "Switch online to start getting calls."}
            </p>
          </div>

          <button 
            onClick={() => setIsWorkerOnline(!isWorkerOnline)}
            className={`w-40 h-40 rounded-full flex flex-col items-center justify-center gap-2 shadow-2xl transition-all active:scale-90 ${
              isWorkerOnline 
              ? 'bg-red-500 shadow-red-200' 
              : 'bg-green-600 shadow-green-200'
            }`}
          >
            <Power size={48} className="text-white" />
            <span className="text-white font-black uppercase tracking-widest">
              {isWorkerOnline ? 'Go Offline' : 'Go Online'}
            </span>
          </button>

          <div className="bg-blue-50 border border-blue-100 p-4 rounded-xl flex items-start gap-3">
             <MapIcon className="text-blue-500 shrink-0 mt-1" size={18} />
             <p className="text-xs text-blue-700 leading-relaxed">
               Current location: <span className="font-bold">Near Connaught Place, Delhi</span>. We update your position every few minutes for accuracy.
             </p>
