  // CUSTOMER HOME
  if (role === 'customer' && step === 'home') {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col">
        <header className="p-6 pb-2">
          <h1 className="text-3xl font-black text-gray-900">Find Workers</h1>
          <p className="text-gray-500">Pick a service to see nearby experts</p>
        </header>

        <main className="p-6 grid grid-cols-2 gap-4">
           {SKILL_CATEGORIES.map((cat) => (
             <button
               key={cat.name}
               onClick={() => handleSkillSelect(cat.name)}
               className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center gap-3 transition-transform active:scale-95 text-center"
             >
               <div className={`p-4 rounded-full ${cat.color}`}>
                 {cat.icon}
               </div>
               <span className="font-bold text-gray-800">{cat.name}</span>
             </button>
           ))}
        </main>
      </div>
    );
  }

  // CUSTOMER SEARCH RESULTS
  if (role === 'customer' && step === 'search') {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col h-screen overflow-hidden">
        <header className="bg-white p-4 shadow-sm flex items-center justify-between z-10">
          <div className="flex items-center gap-3">
            <button onClick={() => setStep('home')} className="p-1"><ChevronLeft /></button>
            <h2 className="font-bold text-lg">{selectedSkill}s Nearby</h2>
          </div>
          <div className="bg-gray-100 p-1 rounded-lg flex">
            <button 
              onClick={() => setViewType('list')}
              className={`p-2 rounded-md ${viewType === 'list' ? 'bg-white shadow-sm' : 'text-gray-400'}`}
            >
              <ListIcon size={18} />
            </button>
            <button 
              onClick={() => setViewType('map')}
              className={`p-2 rounded-md ${viewType === 'map' ? 'bg-white shadow-sm' : 'text-gray-400'}`}
            >
              <MapIcon size={18} />
            </button>
          </div>
        </header>

        <div className="flex-1 relative flex flex-col overflow-hidden">
          {viewType === 'map' ? (
            <div className="absolute inset-0 z-0">
               <MapView 
                  center={userLocation} 
                  workers={filteredWorkers} 
                  onWorkerClick={(w) => {
                    // Logic to highlight or open worker card
                  }} 
               />
               <div className="absolute bottom-6 left-6 right-6 z-10">
                  <WorkerCard worker={filteredWorkers[0]} />
               </div>
            </div>
          ) : (
            <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-20">
              <div className="flex items-center justify-between text-xs text-gray-400 font-bold uppercase tracking-widest px-1">
                <span>{filteredWorkers.length} Workers Available</span>
                <span>Within 5km</span>
              </div>
              {filteredWorkers.length > 0 ? (
                filteredWorkers.map(w => (
                  <WorkerCard key={w.id} worker={w} />
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-20 text-center opacity-50">
                  <Users size={64} className="mb-4 text-gray-300" />
                  <p>No {selectedSkill}s online right now.</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    );
  }

  return null;
};

export default App;

