              />
            </div>
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">{t.mobileNumber}</label>
              <div className="flex gap-2">
                <span className="p-4 bg-gray-200 rounded-xl font-bold">+91</span>
                <input 
                  type="tel" 
                  placeholder="98xxxxxx" 
                  className="flex-1 p-4 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                  value={workerProfile.phone}
                  onChange={(e) => setWorkerProfile({...workerProfile, phone: e.target.value})}
                />
              </div>
            </div>
            {role === 'worker' && (
              <>
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">{t.workCategory}</label>
                  <select 
                    className="w-full p-4 mt-1 bg-white border border-gray-200 rounded-xl outline-none"
                    value={workerProfile.skill}
                    onChange={(e) => setWorkerProfile({...workerProfile, skill: e.target.value as SkillCategory})}
                  >
                    {SKILL_CATEGORIES.map(s => <option key={s.name} value={s.name}>{t.skills[s.name]}</option>)}
                  </select>
