          <button onClick={() => setLang(lang === 'en' ? 'hi' : lang === 'hi' ? 'mr' : 'en')} className="p-2 text-orange-600 flex items-center gap-1">
             <Languages size={18} />
             <span className="text-xs font-bold uppercase">{lang}</span>
          </button>
        </header>

        <main className="p-6 flex-1 flex flex-col items-center justify-center space-y-8">
          <div className="text-center space-y-2">
