        <div className="flex flex-col items-center">
          <div className="w-24 h-24 bg-gradient-to-br from-[#FF6A00] to-[#FF8C37] p-6 rounded-[2.5rem] shadow-2xl shadow-orange-200 mb-8 transform -rotate-6">
             <MapIcon size={48} className="text-white" />
          </div>
          <h1 className="text-5xl font-black text-slate-900 tracking-tight mb-3">
            {t.appName}<span className="text-[#FF6A00]">.</span>
          </h1>
          <p className="text-slate-500 text-lg leading-relaxed max-w-[280px]">
            {t.tagline}
          </p>
        </div>

        <div className="w-full space-y-4 max-w-sm pb-8">
          <button 
            onClick={() => handleRoleSelection('customer')}
            className="group w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-5 rounded-[20px] shadow-xl shadow-slate-200 transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            {t.iNeedWorker}
            <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
          </button>
          <button 
            onClick={() => handleRoleSelection('worker')}
            className="w-full bg-white border border-slate-100 text-slate-600 font-bold py-5 rounded-[20px] hover:bg-gray-50 transition-all active:scale-95"
          >
            {t.iAmWorker}
          </button>
        </div>
      </div>
    );
  }

  if (step === 'onboarding') {
    return (
      <div className="min-h-screen bg-[#FDFDFD] flex flex-col">
        <header className="px-6 py-8 flex items-center justify-between">
          <button onClick={() => setStep('landing')} className="p-3 bg-white shadow-sm border border-gray-100 rounded-2xl text-slate-900"><ChevronLeft size={24}/></button>
          <h2 className="text-xl font-black text-slate-900">{t.onboardingTitle}</h2>
          <div className="w-12" />
        </header>
        <div className="flex-1 px-6 space-y-8">
          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest ml-1">{t.fullName}</label>
              <input 
                type="text" 
                placeholder="Name" 
                className="w-full p-5 bg-white border border-slate-100 rounded-2xl shadow-sm focus:border-[#FF6A00] focus:ring-1 focus:ring-[#FF6A00] outline-none transition-all placeholder:text-gray-300"
                value={workerProfile.name}
                onChange={(e) => setWorkerProfile({...workerProfile, name: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest ml-1">{t.mobileNumber}</label>
              <div className="flex gap-3">
                <span className="p-5 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-900 text-lg">+91</span>
                <input 
                  type="tel" 
                  placeholder="98..." 
                  className="flex-1 p-5 bg-white border border-slate-100 rounded-2xl shadow-sm focus:border-[#FF6A00] outline-none transition-all placeholder:text-gray-300 text-lg"
                  value={workerProfile.phone}
                  onChange={(e) => setWorkerProfile({...workerProfile, phone: e.target.value})}
                />
              </div>
            </div>
            {role === 'worker' && (
              <>
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest ml-1">{t.workCategory}</label>
                  <select 
                    className="w-full p-5 bg-white border border-slate-100 rounded-2xl shadow-sm outline-none appearance-none"
                    value={workerProfile.skill}
                    onChange={(e) => setWorkerProfile({...workerProfile, skill: e.target.value as SkillCategory})}
                  >
                    {SKILL_CATEGORIES.map(s => <option key={s.name} value={s.name}>{t.skills[s.name]}</option>)}
                  </select>
                </div>
              </>
            )}
          </div>
          <button 
            disabled={!workerProfile.name || !workerProfile.phone}
            onClick={handleOnboardingSubmit}
            className="w-full bg-[#FF6A00] disabled:bg-gray-200 text-white font-black py-5 rounded-2xl shadow-xl shadow-orange-100 transition-all active:scale-95"
          >
            {t.startApp}
          </button>
        </div>
      </div>
    );
  }

  if (role === 'customer' && step === 'home') {
    return (
      <div className="min-h-screen bg-[#FDFDFD] flex flex-col pb-12">
        <header className="p-8 pb-4 flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight">{t.findWorkers}</h1>
            <p className="text-slate-500 font-medium text-lg">{t.pickService}</p>
          </div>
        </header>

        <main className="px-6 grid grid-cols-2 gap-5">
           {SKILL_CATEGORIES.map((cat) => (
             <button
               key={cat.name}
               onClick={() => handleSkillSelect(cat.name)}
               className="bg-white p-6 rounded-[28px] border border-slate-50 shadow-sm hover:shadow-md transition-all active:scale-95 flex flex-col items-center gap-4 text-center group"
             >
               <div className={`p-5 rounded-full ${cat.color} transition-transform group-hover:scale-110`}>
                 {cat.icon}
               </div>
               <span className="font-bold text-slate-800 tracking-tight">{t.skills[cat.name]}</span>
             </button>
           ))}
        </main>
      </div>
    );
  }

  if (role === 'customer' && step === 'search') {
    return (
      <div className="min-h-screen bg-white flex flex-col h-screen overflow-hidden">
        <header className="px-6 py-6 border-b border-gray-50 flex items-center justify-between bg-white/80 backdrop-blur-md sticky top-0 z-20">
          <div className="flex items-center gap-4">
            <button onClick={() => setStep('home')} className="p-2 bg-gray-50 rounded-xl"><ChevronLeft size={20}/></button>
            <h2 className="font-black text-xl text-slate-900">{t.skills[selectedSkill!] || selectedSkill}</h2>
          </div>
          <div className="bg-gray-100 p-1.5 rounded-2xl flex shadow-inner">
            <button onClick={() => setViewType('list')} className={`p-2.5 rounded-xl transition-all ${viewType === 'list' ? 'bg-white shadow-sm text-[#FF6A00]' : 'text-gray-400'}`}>
              <ListIcon size={20} />
            </button>
            <button onClick={() => setViewType('map')} className={`p-2.5 rounded-xl transition-all ${viewType === 'map' ? 'bg-white shadow-sm text-[#FF6A00]' : 'text-gray-400'}`}>
              <MapIcon size={20} />
            </button>
          </div>
        </header>

        <div className="flex-1 relative flex flex-col overflow-hidden bg-[#FDFDFD]">
          {viewType === 'map' ? (
            <div className="absolute inset-0 z-0">
               <MapView center={userLocation} workers={filteredWorkers} onWorkerClick={() => {}} />
               <div className="absolute bottom-8 left-6 right-6 z-10">
                  <WorkerCard worker={filteredWorkers[0]} />
               </div>
            </div>
          ) : (
            <div className="flex-1 overflow-y-auto px-6 py-6 space-y-5 pb-24">
              <div className="flex items-center justify-between px-1">
                <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em]">{filteredWorkers.length} {t.available}</span>
                <span className="text-[11px] font-black text-[#FF6A00] uppercase tracking-widest">NEARBY</span>
              </div>
              {filteredWorkers.length > 0 ? (
                filteredWorkers.map(w => <WorkerCard key={w.id} worker={w} />)
              ) : (
                <div className="flex flex-col items-center justify-center py-32 text-center">
                  <div className="p-10 bg-gray-50 rounded-full mb-6">
                    <Users size={48} className="text-gray-200" />
                  </div>
                  <p className="text-slate-400 font-bold">{t.noWorkers}</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    );
  }

  // Fallback for Worker flow to maintain parity
  if (role === 'worker' && step === 'home') {
    return (
      <div className="min-h-screen bg-[#FDFDFD] flex flex-col">
        <header className="p-8 flex items-center justify-between">
          <h1 className="text-3xl font-black text-slate-900">{t.dashboard}</h1>
          <button className="p-3 bg-white shadow-sm border border-gray-100 rounded-2xl text-slate-400">
            <Settings size={24} />
          </button>
        </header>

        <main className="p-8 flex-1 flex flex-col items-center justify-center space-y-12">
          <div className="text-center space-y-3">
             <div className={`mx-auto w-3 h-3 rounded-full animate-pulse ${isWorkerOnline ? 'bg-green-500' : 'bg-red-400'}`} />
             <h3 className="text-4xl font-black text-slate-900 tracking-tight">
               {isWorkerOnline ? t.online : t.offline}
             </h3>
             <p className="text-slate-400 font-medium">
               {isWorkerOnline ? "Currently visible to customers" : "Not receiving calls right now"}
             </p>
          </div>

          <button 
            onClick={() => setIsWorkerOnline(!isWorkerOnline)}
            className={`w-64 h-64 rounded-[4rem] flex flex-col items-center justify-center gap-4 transition-all duration-500 shadow-2xl active:scale-95 ${
              isWorkerOnline 
              ? 'bg-slate-900 shadow-slate-200' 
              : 'bg-[#FF6A00] shadow-orange-100'
            }`}
          >
            <Power size={64} className="text-white" />
            <span className="text-white font-black uppercase tracking-[0.2em] text-sm">
              {isWorkerOnline ? t.goOffline : t.goOnline}
            </span>
          </button>
        </main>

        <nav className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-gray-50 p-6 flex justify-around items-center">
           <div className="flex flex-col items-center text-[#FF6A00]">
             <UserCircle size={28} />
             <span className="text-[10px] font-black uppercase tracking-widest mt-2">{t.profile}</span>
           </div>
           <div className="flex flex-col items-center text-slate-300">
             <Phone size={28} />
             <span className="text-[10px] font-black uppercase tracking-widest mt-2">{t.history}</span>
           </div>
        </nav>
      </div>
    );
  }

  return null;
};

export default App;

